-- Outbound dialing support (Phase 2, Kashif): AMD voicemail + dial-policy lookups.
--
-- voicemail_message  — the tenant-approved message left when answering-machine
--                      detection finds voicemail (plan §08). NULL = hang up
--                      without leaving one. Never generated by the LLM.
-- Index              — the dial policy counts prior attempts per number on
--                      every dial, immediately before the dial.

ALTER TABLE ivr_bot_configs
    ADD COLUMN IF NOT EXISTS voicemail_message TEXT;

CREATE INDEX IF NOT EXISTS idx_dial_attempts_number
    ON dial_attempts(tenant_id, phone_number, dialed_at DESC);

CREATE INDEX IF NOT EXISTS idx_dial_attempts_call
    ON dial_attempts(call_id) WHERE call_id IS NOT NULL;
